const rm = id => ({n:"AI at Work Roadmap item "+id,u:"https://www.microsoft.com/en-us/microsoft-365/roadmap?id="+id});

const TILES = [
 {p:"Copilot app",ic:"home",t:"Home reaches everyone, and hands bigger jobs to Cowork",s:"Rolling out",when:"Rolling out worldwide from Nov 2026",front:"Home, the one place to start in the Copilot app with Chat and Cowork side by side, is now rolling out worldwide. When a request needs more than a chat, Copilot suggests moving it to Cowork and carries the conversation across.",why:"Every staff member will see a new starting screen. Work handed to Cowork uses Copilot Credits, so check your spending settings before the suggestion reaches everyone.",detail:"The Book of News says Home is now rolling out worldwide, and that Auto's suggestion to move complex work from Chat to Cowork is generally available. Auto in Cowork, which sets the effort for each step, is available to Frontier customers, and Cowork calling your organisation's own declarative agents is in private preview through Frontier.",src:["bon", "igcopilot", 577841],h:2},
 {p:"Copilot app",ic:"office",t:"Word, Excel and PowerPoint open inside the Copilot app",s:"GA",when:"Generally available now",front:"Office in Copilot brings full Word, Excel and PowerPoint into the Copilot app, so a request can become a finished document, workbook or deck beside the conversation, with colleagues editing at the same time.",why:"Files save to OneDrive and keep your permissions, sensitivity labels and compliance controls from the first draft, so the usual records and sharing rules apply.",detail:"The Book of News lists Office in Copilot as generally available. Microsoft's Office blog says the file opens next to the conversation, can be shaped with prompts or edited by hand, and can move into the full Office apps at any time. Microsoft's Copilot blog says it is included in the Copilot licence.",src:["bon", "igoffice", "igcopilot"],h:2},
 {p:"Copilot app",ic:"cal",t:"Today: your day sorted, with drafts ready to approve",s:"Private preview",when:"Private preview through Frontier, starting soon",front:"Today gathers email, calendar, chats and meetings into one view of what matters now and what can wait, with draft replies, messages and schedule changes ready for the person to review and approve.",why:"The morning Today Brief is included with a Microsoft Copilot licence, but the Today Feed's updates through the day use Copilot Credits, so it belongs in your spending plan.",detail:"The Book of News says Today will begin rolling out in private preview through the Frontier program, in the Copilot app and in Outlook. Microsoft's Office blog says it needs no prompts, agent set-up or workflow configuration.",src:["bon", "igoffice"],h:2},
 {p:"Copilot app",ic:"learn",t:"Workspaces: one place for a team and Copilot",s:"Frontier",when:"Frontier now; updates in preview from Nov 2026",front:"Copilot Workspaces, the next step for Copilot Notebooks, give a team one shared space for a project. Copilot suggests the right workspace and points out what changed, what is unresolved and what is due.",why:"A workspace pools files and context for everyone in it, so who belongs decides what Copilot can draw on. Each person's Autopilot can join a workspace soon.",detail:"The Book of News says Workspaces are available in the Copilot app through the Frontier program, and that bringing your personal Autopilot into a workspace is coming soon. The AI at Work Roadmap lists workspace updates and workspace memory in preview from November 2026.",src:["bon", "igoffice", 579889, 580869],h:2},
 {p:"Copilot app",ic:"watch",t:"Autopilot starts rolling out to Frontier",s:"Frontier",when:"Rolling out to Frontier now",front:"Autopilot, a long-running personal agent with its own identity, memory and tools, is rolling out to Frontier customers. It follows up on threads, runs recurring work, and colleagues can @mention someone's Autopilot in a Teams channel or group chat.",why:"Every action is tied to the agent's own ID, safety-checked and visible to admins. Decide who may try it, what needs approval and how its Copilot Credits are capped before turning it on.",detail:"The Book of News says Autopilot is rolling out through the Frontier program and appears in the Copilot app's left navigation. Entra Agent ID for Microsoft cloud agents, including Autopilot, is in preview, and Agent 365 Cost Management lists Autopilot among the usage-based services it tracks.",src:["bon", "igcopilot"],h:2},
 {p:"Agents & Studio",ic:"builder",t:"Copilot Code builds apps, and is generally available in December",s:"Frontier",when:"Frontier now; GA Dec 2026",front:"Copilot Code turns a plain-language request into a working dashboard, tracker or app, built in a secure sandbox inside your tenant, on Windows, the web, iOS and Android.",why:"Apps publish through Copilot Managed Runtime and are managed in the Microsoft 365 admin center, so decide now who may build and publish, and who owns each app.",detail:"The Book of News says Copilot Code is available in the Frontier program and will be generally available in December. A new local sandbox limits what Code can read, write and reach on Windows, with macOS coming soon. Copilot Managed Runtime, which hosts what people build in Code, Cowork and Copilot Studio, is now generally available and adds an optional Microsoft Fabric data backend.",src:["bon", "igcopilot", 571887],h:2},
 {p:"Security & governance",ic:"gauge",t:"Agent 365 shows what AI costs, and what it delivers",s:"Preview",when:"Preview now; Business Analytics in Frontier",front:"Agent 365 Cost Management in the Microsoft admin center brings usage-based AI spending into one place, from Cowork, Code and Autopilot to Copilot Studio, with policies, limits and alerts. Business Analytics adds value measures such as task success and hours assisted.",why:"This is how budget holders see credits before they surprise anyone. Insights for Microsoft services need at least one Microsoft Copilot licence in the tenant; other services need an Agent 365 licence.",detail:"The Book of News says spend drivers, policies, limits, alerts and chargeback through Fabric are in preview, and that forecasting, plain-language questions and recommendations come to the Frontier program this month. Agent 365 Business Analytics is available in the Frontier program, and in December its value insights extend to non-Microsoft agents.",src:["bon", "igsrc", 577548],h:2},
 {p:"Security & governance",ic:"gauge",t:"Agent usage reports for Microsoft agents, with no extra licence",s:"GA",when:"Generally available now",front:"Usage and activity for Microsoft's own agents, and agents built on Microsoft platforms, now show in the Microsoft admin center whatever your Agent 365 licensing: active users, sessions, exception rate and run time.",why:"A quick view of which agents people really use. Full governance, risk and third-party insights still need an Agent 365 or Microsoft 365 E7 licence.",detail:"The Book of News says these management insights are generally available. Viva Insights no longer needs an Agent 365 licence for agent insights, but still needs 50 or more assigned Copilot licences.",src:["bon"],h:1},
 {p:"Security & governance",ic:"plug",t:"Plugins and skills are managed centrally for Copilot and Cowork",s:"GA",when:"Generally available now",front:"Admins can now manage plugins and skills for Copilot and Cowork in one place and assign them to users and groups in the Microsoft 365 admin center.",why:"Skills and plugins carry instructions and data access, so they need an approval path like agents do. Decide who may publish them before people start sharing their own.",detail:"The Book of News lists plugins and skills governance as generally available, alongside previews for governing MCP servers and tools, local and shadow agents, and agent classification in Agent Map. An action center for inactive and ownerless agents is expected in private preview in December.",src:["bon"],h:1},
 {p:"Agents & Studio",ic:"iq",t:"Microsoft IQ is generally available",s:"GA",when:"Generally available now",front:"Microsoft IQ brings Work IQ, Fabric IQ, Foundry IQ and Web IQ together as one way to give Copilot and agents your organisation's context, with no new product to buy.",why:"It changes what agents can draw on across the organisation, so permissions, labels and oversharing clean-up decide how safe it is. Business plugins, packaged know-how for a line of work, are in Frontier.",detail:"The Book of News says Microsoft IQ is now generally available, with no new SKU or subscription, and pairs with Agent 365 for governance. The context capabilities and the reusable plugins, skills, tools and agents are generally available; business plugins are available in the Frontier program.",src:["bon", "igsrc"],h:2},
 {p:"Agents & Studio",ic:"auto",t:"Work IQ: agents that react to events, inside your limits",s:"Preview",when:"Preview now",front:"Work IQ adds a listen capability so agents can act when something happens, such as a new message, plus admin limits on what agents may do and human approval steps.",why:"Admins set a tenant-wide ceiling on agent actions, for example read, create and update but never delete, and each agent's policy can only narrow it. Set that ceiling before agents start acting on their own.",detail:"The Book of News says richer context and more ways to act are generally available, while listen and the expanded enterprise controls are in preview. Microsoft's Work IQ blog describes the tenant-wide upper limit, and says agents registered in Agent 365 are checked against their approved policy on every call.",src:["bon", "igworkiq"],h:2},
 {p:"Security & governance",ic:"shield",t:"Purview will stop Copilot using sensitive files, even unlabelled ones",s:"Planned",when:"Public preview from Jan 2027",front:"New Purview data loss prevention rules will stop Copilot processing files that hold sensitive information even when nobody has labelled them, and will check files attached or linked in prompts.",why:"Labels no longer have to be finished before this protection works, which removes a common blocker. Plan which sensitive information types to start with.",detail:"Microsoft's Purview Ignite post says this is in public preview from January 2027, with the same protection for local agents on Windows and more precise built-in sensitive information types. Auto-labelling now handles up to 500,000 files a day and is generally available.",src:["igpurview", "bon", 577862, 579195],h:2},
 {p:"Security & governance",ic:"shield",t:"Defender and Intune watch the AI agents on your devices",s:"GA",when:"Generally available now; Intune controls in preview",front:"Defender for Endpoint now checks local AI agents on Windows, such as coding assistants, for hidden malicious instructions in Audit or Block mode, and Intune can flag devices running agents you have not approved.",why:"Staff are installing AI tools that act on their behalf. This gives security teams a way to see and limit them on managed devices.",detail:"The Book of News says Defender's runtime protection for local agents is generally available for Defender for Endpoint Plan 2 customers, set up in Defender or Intune. Intune's local AI agent governance, which can mark devices with unapproved agents noncompliant and block them through Conditional Access, is in preview. Entra Agent ID for discovered local agents is also in preview.",src:["bon", "igdefender"],h:2},
 {p:"Security & governance",ic:"lock",t:"Help to secure Exchange Server and SharePoint Server",s:"Rolling out",when:"Some protections now; more over time",front:"Microsoft is starting an on-premises security push for supported Exchange Server, SharePoint Server and Skype for Business Server, including a baseline security mode with safer settings built in.",why:"Some protections and guidance are available today, and more will follow by product. Microsoft still recommends moving eligible workloads to Microsoft 365.",detail:"The Book of News says guidance will soon appear in Secure Now, and that faster security updates, safer settings and temporary protections against emerging threats will roll out over time, with availability varying by product and workload.",src:["bon"],h:1},
 {p:"Copilot app",ic:"cloud",t:"Copilot on Windows can tidy files and check your PC",s:"Preview",when:"Preview now",front:"In preview, Copilot on Windows can find, organise, move and rename local files from a plain-language request, troubleshoot the PC using Windows diagnostics, and answer from the new Windows Search on the taskbar.",why:"People opt in through Settings and IT can manage it by policy, so decide your position before staff ask.",detail:"The Book of News says all three are in preview. Microsoft's Windows blog says local context, actions and models are coming soon to Copilot on Copilot+ PCs.",src:["bon", "igwin"],h:1},
 {p:"Agents & Studio",ic:"globe",t:"Edge turns a recorded workflow into a Cowork skill",s:"Preview",when:"Preview now",front:"Edge for Business can record a workflow done in the browser and turn it into a reusable skill for Cowork, and IT can make agents browse only through Edge, each in its own window with its own Entra identity.",why:"Recorded skills run within the person's own permissions, but they are still new automations. Decide who may record and share them.",detail:"The Book of News says the skills recorder is in preview with Cowork and managed agent browsing is in preview. Extension safety scores are generally available, while extension leak control, a Microsoft Sentinel connector and Global Secure Access in Edge are in preview.",src:["bon"],h:1},
 {p:"Security & governance",ic:"shield",t:"Microsoft Perception security agents are generally available",s:"GA",when:"Generally available now",front:"Microsoft Perception, a team of security agents that triage alerts, investigate and work through playbooks, is now generally available. Its triage agent covers about 80% of a typical Defender alert queue.",why:"Security teams can hand routine triage to agents, with least-privilege access, approvals, an audit trail and a cost calculator.",detail:"The Book of News says Perception, formerly Project Perception, is generally available, including the agents and playbooks announced in July. A web app penetration test agent and a reduce exposure risk playbook are in preview, and secure AI agents playbooks are in private preview.",src:["bon", "igsec"],h:1},
 {p:"Copilot app",ic:"model",t:"GPT-6.2 Sol and Astra join the models in Copilot",s:"Rolling out",when:"Rolling out from 20 Nov 2026",front:"OpenAI's GPT-6.2 Sol is rolling out to eligible users in Copilot Chat, Cowork, Copilot Studio and Copilot in Word, Excel and PowerPoint. GPT-6.2 Astra is rolling out in Cowork and Copilot Studio, and Frontier users can also choose it in Chat and the Office apps.",why:"New models can reach the model picker before agency guidance catches up. Check which models are allowed in the Microsoft 365 admin centre, then update staff guidance and help desk notes.",detail:"Microsoft announced both models on 20 November 2026 as a gradual rollout, so they can reach organisations and regions at different times. Admins choose which models people can use in the Microsoft 365 admin centre. Microsoft's Cowork update from Ignite also lists the new models, and Microsoft Learn notes that in November GPT 5.5 left the Cowork model picker, replaced by GPT 6.1 Sol hosted by Microsoft in Azure.",src:["gpt62","igcowork","coworknew"],h:2},
 {p:"Security & governance",ic:"shield",t:"Baseline Security Mode 2026 is generally available",s:"GA",when:"Generally available, rolling out in phases",front:"Microsoft's recommended security baseline for Microsoft 365 adds 24 settings and an Applications category, and now reaches Intune, Purview and Dynamics 365. Admins can apply each setting on its own, or run it in simulation first.",why:"It gives IT and security teams a Microsoft-recommended baseline to test safely and compare with your own standards, especially for guest access and apps with broad permissions.",detail:"Microsoft's announcement of 17 November 2026 lists settings such as multifactor authentication for guests, keeping guests out of eDiscovery roles, a second admin to approve sensitive Intune actions and blocking new classic SharePoint pages. Global admins find it under Org settings in the Microsoft 365 admin centre. Some parts, such as Azure and Windows settings and downloadable reports, are in private preview.",src:["bsm26"],h:2},
 {p:"Copilot app",ic:"model",t:"Claude Fable 5.2 reaches Cowork, and needs data retention",s:"Rolling out",when:"Rolling out from 11 Nov 2026",front:"Anthropic's Claude Fable 5.2 is rolling out in Copilot Cowork and Copilot Studio, and replaces Fable 5.1 in the Cowork model picker for select customers.",why:"Microsoft Learn says Fable 5.2 requires data retention by the model provider. Privacy and security teams should decide whether that fits agency policy before staff can choose it. Admins can turn models off under Copilot settings in the Microsoft 365 admin centre.",detail:"Microsoft's Copilot Blog announced Fable 5.2 on 11 November 2026. Microsoft Learn's What's new in Copilot Cowork lists it for select customers in November 2026, replacing Fable 5.1, and notes that it requires data retention. Microsoft's page on choosing a model for Cowork explains what that means for Anthropic models.",src:["fable52","coworknew","coworkmodels"],h:2},
 {p:"Everyday apps",ic:"chat",t:"Teams will let admins decide who can record and transcribe",s:"Planned",when:"Roadmap target Dec 2026",front:"A new meeting policy will let admins limit who can start recording and transcription to organisers and co-organisers, or extend it to presenters, and decide whether organisers may change that choice.",why:"Recordings and transcripts often hold personal information and can be public records. Central control over who starts them helps apply privacy and records rules the same way in every meeting.",detail:"AI at Work Roadmap item 579860 targets December 2026 for worldwide and government clouds. Separately, Microsoft's release notes of 17 November 2026 say admins can now customise part of the notice people see when recording or transcription starts in a Teams call.",src:[579860,"relnotes"],h:2},
 {p:"Security & governance",ic:"lock",t:"Teams will admit only the outside notetakers you approve",s:"Planned",when:"Roadmap target Jan 2027",front:"Admins will be able to list the external meeting bots, such as third-party AI notetakers, that may join meetings your organisation hosts. Other bots can be blocked or held in the lobby for approval.",why:"An outside notetaker can copy meeting content beyond your control. An approved list lets you admit tools you have assessed and keep the rest out.",detail:"AI at Work Roadmap item 580451 targets January 2027 for worldwide and GCC tenants. An allowed bot is treated like any other external participant, so your meeting policies still apply to it.",src:[580451],h:2},
 {p:"Security & governance",ic:"shield",t:"Exchange Online can now reject spoofed Direct Send mail",s:"GA",when:"Generally available since 16 Nov 2026",front:"When an admin turns on Reject Direct Send, Exchange Online refuses anonymous messages that use one of your own domains as the sender, closing a common way to fake internal mail.",why:"Mail that pretends to come from your own domain is a common phishing trick. Move printers, scanners and business systems that rely on Direct Send to connectors first, then switch it on.",detail:"The Exchange Team announced general availability on 16 November 2026. It stays off for existing tenants until an admin turns it on, and is on by default for new tenants. The Change Optics Report shows which devices and services still send this way.",src:["directsend"],h:1},
 {p:"Security & governance",ic:"sp",t:"SharePoint shows which agents reach your sites, and limits them",s:"GA",when:"Generally available now; more in Dec 2026",front:"A new Agent governance area in the SharePoint admin centre shows how many agents reach SharePoint, OneDrive and Teams content, which sites they use most and how that splits by sensitivity label.",why:"Records and security teams can see which agents touch sensitive sites and narrow their access, which supports least-privilege access as agent use grows.",detail:"Microsoft's SharePoint blog of 17 November 2026 says restricting apps and agents at site level, and the SharePoint Admin Agent's oversharing, lifecycle and storage skills, are generally available now. The Agent Access Heatmap and a Governance Hub for admins are due in December 2026. The Admin Agent needs SharePoint Advanced Management.",src:["spagents","spadminagent"],h:2},
 {p:"Microsoft IQ",ic:"iq",t:"Copilot can answer questions about your people and teams",s:"Rolling out",when:"Rolling out through Dec 2026; some parts in Frontier",front:"Work IQ can now use people and organisation data, so Copilot can answer questions about reporting lines, team make-up and skills. Some parts are generally available and others are in Frontier.",why:"Before HR data feeds Copilot's answers, privacy and HR teams should agree which attributes to share. A related admin setting, off by default, makes shared custom attributes visible to everyone in the tenant, guests included.",detail:"Microsoft's Copilot Blog introduced people and organisation context in Work IQ on 16 November 2026, with the rollout running through December. Microsoft says it is meant for understanding the organisation, not for monitoring performance. The setting to share custom organisational attributes is in the release notes of 17 November 2026.",src:["peoplectx","relnotes"],h:2},
 {p:"Everyday apps",ic:"cal",t:"Planner brings tasks and plans together, and moves on from Dataverse plans",s:"GA",when:"Available now; more on the roadmap",front:"Unified plans bring To Do, basic plans and premium plans into one service across Outlook, Teams, Planner and Loop, and now Copilot and Cowork. Premium features follow each person's licence.",why:"Microsoft says it will no longer invest in Dataverse-based plans. Teams that run projects in premium plans should start planning the move, and IT should check integrations built on the older plan connectors and APIs.",detail:"Announced on the Planner Blog on 18 November 2026. Sprints and backlogs (roadmap 581629, January 2027) and task hierarchy (roadmap 580879, March 2027) are on the way. Premium plans stay supported during the move, and Microsoft has not given an end date.",src:["planner",581629,580879],h:1},
 {p:"Agents & Studio",ic:"builder",t:"Copilot Studio workflows run Python and make documents",s:"Planned",when:"Roadmap targets Nov and Dec 2026",front:"A new Code node runs Python as a step in a workflow, written by hand or generated from a description, and the Agent node can hand files such as PDF, Word, Excel and CSV to later steps.",why:"Workflows owned by an app registration, or shared with co-owners, are less likely to break when someone leaves. Python steps are new code, so give them the same review and testing as any other code.",detail:"AI at Work Roadmap items 580866 (Python steps) and 580865 (documents from the Agent node) target November 2026; 580864 (co-owners) and 580863 (an app registration as owner) target December 2026. All are worldwide. Microsoft's Copilot Studio blog of 11 November 2026 maps which admin governs each part of an agent's life.",src:[580866,580865,580864,580863,"studiogov"],h:2},
 {p:"Copilot app",ic:"card",t:"Pages: interactive reports and dashboards, made with Copilot",s:"Preview",when:"Preview Nov 2026; GA Dec 2026",front:"Start a Page with a prompt and bring together content, charts and interactive elements in one shareable Page that colleagues and agents can work on. Comments on the Page can ask Copilot for targeted edits.",why:"A Page is a shared Microsoft 365 file, so it follows your sharing and records rules. Agree where finished reports are kept before teams build their first dashboards in it.",detail:"AI at Work Roadmap items 580445 (reports and dashboards) and 580449 (Copilot edits on the Page) show preview in November 2026 and general availability in December 2026, worldwide.",src:[580445,580449],h:1},
 {p:"Copilot app",ic:"learn",t:"What Microsoft learned rolling out Cowork to its own staff",s:"GA",when:"Microsoft Inside Track, 12 Nov 2026",front:"Microsoft's own IT team found that switching Cowork on did not change habits by itself. Peer stories with real prompts, steady reminders over months, findable guidance and measures set up before launch made the difference.",why:"Agencies planning a Cowork rollout can borrow these lessons, above all budgeting for months of follow-up support and deciding how to measure use before launch.",detail:"Published on Microsoft Inside Track on 12 November 2026. Microsoft Learn's November update to What's new in Copilot Cowork also adds guidance on planning business processes with Cowork and starting with a pilot before expanding.",src:["coworkstick","coworknew"],h:1},
 {p:"Everyday apps",ic:"phone",t:"Teams can build a voice profile from meeting audio, if staff opt in",s:"GA",when:"Generally available since 17 Nov 2026",front:"People without a voice profile can opt in from Teams settings and build one from audio in their meetings. It supports voice isolation, speaker recognition in rooms and transcripts, and richer meeting recaps.",why:"Voice profiles are biometric information. Privacy teams may want to confirm the admin setting matches agency policy, and that staff understand what enrolling means.",detail:"Listed in Microsoft's release notes of 17 November 2026 as express voice enrolment, for Teams on Windows and Mac. Admins can turn it on or off for the organisation.",src:["relnotes"],h:1}
];

